from collections import Counter

def can_we_give(freq, packets, n):
    fullfilled = 0
    for food_packets in freq.keys():
        fullfilled += freq[food_packets] // packets
    if fullfilled >= n:
        return True
    else:
        return False


def main():
    n, m = (int(num) for num in input().split())
    A = [int(num) for num in input().split()]
    if m < n:
        print(0)
        return
    freq = Counter(A)
    l, r = 1, max(freq.values())
    while l < r:
        mid = (l + r + 1) // 2
        if can_we_give(freq, mid, n):
            l = mid
        else:
            r = mid - 1
    print(l)

if __name__ == '__main__':
    main()

from collections import defaultdict
d = defaultdict(int)
n,m = map(int,input().split())
if n > m:
    print(0)
else:
    food_type = list(map(int,input().split()))
    for f in food_type:
        d[f] += 1

    d_ls = sorted(d.items(), key=lambda k: k[1], reverse=True)
    max_d = min(d_ls[0][1], m//n)
    ret = 0

    for i in range(1, max_d+1):
        s = sum([f[1] // i for f in d_ls])

        if s < n:
            ret = i-1
            break
    else:
        ret = max_d
    print(ret)

def Ludi(t, d):
    sum = 0
    if t != 0:
        for i in d:
            sum += d[i] // t
        return sum
    else:
        return 0

